content:
Service Worker 深入理解与实践1. Service Worker 简介Service Worker 是一种运行在浏览器后台的脚本,独立于网页存在,为 Web 应用提供了拦截和处理网络请求、管理缓存资源、推送消息等能力,是构建 PWA(Progressive Web App)应用的核心技术。
核心特点
独立线程:运行在独立的 Worker 线程中,不会阻塞主线程
网络代理:可以拦截和处理网页发出的所有网络请求
离线能力:通过缓存策略实现离线访问
生命周期:有独立的注册、安装、激活生命周期
HTTPS 要求:出于安全考虑,必须在 HTTPS 环境下运行(localhost 除外)
作用域:基于路径的作用域控制,决定可以控制哪些页面

与 Web Worker 的区别12345// Web Worker: 页面级别,页面关闭即销毁const worker = new Worker('worker.js');// Service Worker: 应用级别,可持续存在navigator.serviceWorker.register('/sw.js');

主要区别:

生命周期:Service Worker 可以在页面关闭后继续运行
功能范围:Service Worker 可以拦截网络请求,Web Worker 不行
作用域:Service Worker 控制整个应用,Web Worker 只服务于单个页面
事件模型:Service Worker 基于事件驱动,可以被浏览器唤醒

2. Service Worker 生命周期完整生命周期流程123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566// 1. 注册阶段navigator.serviceWorker.register('/sw.js', {  scope: '/'}).then(registration =&gt; {  console.log('Service Worker 注册成功:', registration.scope);    // 检查不同状态的 Service Worker  if (registration.installing) {    console.log('Service Worker 正在安装');  } else if (registration.waiting) {    console.log('Service Worker 已安装,等待激活');  } else if (registration.active) {    console.log('Service Worker 已激活');  }}).catch(error =&gt; {  console.error('Service Worker 注册失败:', error);});// 2. 在 sw.js 中:安装阶段self.addEventListener('install', event =&gt; {  console.log('Service Worker 安装中...');    event.waitUntil(    caches.open('v1').then(cache =&gt; {      // 预缓存关键资源      return cache.addAll([        '/',        '/index.html',        '/styles.css',        '/app.js',        '/logo.png'      ]);    }).then(() =&gt; {      // 立即激活新 Service Worker      return self.skipWaiting();    })  );});// 3. 激活阶段self.addEventListener('activate', event =&gt; {  console.log('Service Worker 激活中...');    event.waitUntil(    // 清理旧缓存    caches.keys().then(cacheNames =&gt; {      return Promise.all(        cacheNames          .filter(cacheName =&gt; cacheName !== 'v1')          .map(cacheName =&gt; caches.delete(cacheName))      );    }).then(() =&gt; {      // 立即控制所有页面      return self.clients.claim();    })  );});// 4. 工作阶段self.addEventListener('fetch', event =&gt; {  event.respondWith(    caches.match(event.request).then(response =&gt; {      return response || fetch(event.request);    })  );});

生命周期状态转换12345678910111213141516171819// 监听 Service Worker 状态变化navigator.serviceWorker.register('/sw.js').then(registration =&gt; {  let serviceWorker;    if (registration.installing) {    serviceWorker = registration.installing;  } else if (registration.waiting) {    serviceWorker = registration.waiting;  } else if (registration.active) {    serviceWorker = registration.active;  }    if (serviceWorker) {    serviceWorker.addEventListener('statechange', e =&gt; {      console.log('状态变更:', e.target.state);      // 可能的状态: installing -&gt; installed -&gt; activating -&gt; activated    });  }});

更新策略1234567891011121314151617181920212223242526272829303132333435363738394041424344// sw.js - 版本控制const CACHE_VERSION = 'v2'; // 修改版本号触发更新self.addEventListener('install', event =&gt; {  event.waitUntil(    caches.open(CACHE_VERSION).then(cache =&gt; {      return cache.addAll([        '/index.html',        '/styles.css',        '/app.js'      ]);    })  );});// 主页面 - 检测更新navigator.serviceWorker.register('/sw.js').then(registration =&gt; {  // 每小时检查一次更新  setInterval(() =&gt; {    registration.update();  }, 3600000);    // 监听更新  registration.addEventListener('updatefound', () =&gt; {    const newWorker = registration.installing;        newWorker.addEventListener('statechange', () =&gt; {      if (newWorker.state === 'installed' &amp;&amp; navigator.serviceWorker.controller) {        // 新版本已安装,提示用户刷新        if (confirm('发现新版本,是否立即更新?')) {          newWorker.postMessage({ type: 'SKIP_WAITING' });          window.location.reload();        }      }    });  });});// sw.js - 接收跳过等待消息self.addEventListener('message', event =&gt; {  if (event.data.type === 'SKIP_WAITING') {    self.skipWaiting();  }});

3. 缓存策略详解1. Cache First (缓存优先)123456789101112131415161718// 适用场景:静态资源(CSS、JS、图片等)self.addEventListener('fetch', event =&gt; {  event.respondWith(    caches.match(event.request).then(cachedResponse =&gt; {      if (cachedResponse) {        return cachedResponse; // 返回缓存      }            return fetch(event.request).then(response =&gt; {        // 缓存新请求的资源        return caches.open('v1').then(cache =&gt; {          cache.put(event.request, response.clone());          return response;        });      });    })  );});

2. Network First (网络优先)123456789101112131415161718// 适用场景:API 请求、动态内容self.addEventListener('fetch', event =&gt; {  event.respondWith(    fetch(event.request)      .then(response =&gt; {        // 更新缓存        const responseClone = response.clone();        caches.open('v1').then(cache =&gt; {          cache.put(event.request, responseClone);        });        return response;      })      .catch(() =&gt; {        // 网络失败,返回缓存        return caches.match(event.request);      })  );});

3. Stale While Revalidate (过期重验证)1234567891011121314151617// 适用场景:需要快速响应但也要保持更新的资源self.addEventListener('fetch', event =&gt; {  event.respondWith(    caches.match(event.request).then(cachedResponse =&gt; {      const fetchPromise = fetch(event.request).then(response =&gt; {        // 后台更新缓存        caches.open('v1').then(cache =&gt; {          cache.put(event.request, response.clone());        });        return response;      });            // 立即返回缓存,同时更新      return cachedResponse || fetchPromise;    })  );});

4. Network Only (仅网络)123456// 适用场景:始终需要最新数据的请求self.addEventListener('fetch', event =&gt; {  if (event.request.url.includes('/api/real-time')) {    event.respondWith(fetch(event.request));  }});

5. Cache Only (仅缓存)1234// 适用场景:离线应用的静态资源self.addEventListener('fetch', event =&gt; {  event.respondWith(caches.match(event.request));});

综合策略实现1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768const CACHE_NAME = 'my-app-v1';const STATIC_CACHE = 'static-v1';const DYNAMIC_CACHE = 'dynamic-v1';self.addEventListener('fetch', event =&gt; {  const { request } = event;  const url = new URL(request.url);    // 根据请求类型应用不同策略  if (request.method !== 'GET') {    // POST/PUT/DELETE 等请求不缓存    event.respondWith(fetch(request));    return;  }    if (url.pathname.startsWith('/api/')) {    // API 请求:网络优先    event.respondWith(networkFirst(request, DYNAMIC_CACHE));  } else if (request.destination === 'image') {    // 图片:缓存优先    event.respondWith(cacheFirst(request, STATIC_CACHE));  } else {    // 其他资源:过期重验证    event.respondWith(staleWhileRevalidate(request, CACHE_NAME));  }});// 缓存优先实现async function cacheFirst(request, cacheName) {  const cached = await caches.match(request);  if (cached) return cached;    try {    const response = await fetch(request);    const cache = await caches.open(cacheName);    cache.put(request, response.clone());    return response;  } catch (error) {    return new Response('Offline', { status: 503 });  }}// 网络优先实现async function networkFirst(request, cacheName) {  try {    const response = await fetch(request);    const cache = await caches.open(cacheName);    cache.put(request, response.clone());    return response;  } catch (error) {    const cached = await caches.match(request);    return cached || new Response('Offline', { status: 503 });  }}// 过期重验证实现async function staleWhileRevalidate(request, cacheName) {  const cached = await caches.match(request);    const fetchPromise = fetch(request).then(response =&gt; {    caches.open(cacheName).then(cache =&gt; {      cache.put(request, response.clone());    });    return response;  });    return cached || fetchPromise;}

4. 在 React 中集成 Service Worker基础注册组件12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849// src/serviceWorkerRegistration.jsexport function register(config) {  if ('serviceWorker' in navigator) {    window.addEventListener('load', () =&gt; {      const swUrl = `${process.env.PUBLIC_URL}/service-worker.js`;            navigator.serviceWorker        .register(swUrl)        .then(registration =&gt; {          registration.onupdatefound = () =&gt; {            const installingWorker = registration.installing;                        if (installingWorker == null) return;                        installingWorker.onstatechange = () =&gt; {              if (installingWorker.state === 'installed') {                if (navigator.serviceWorker.controller) {                  // 新内容可用                  if (config &amp;&amp; config.onUpdate) {                    config.onUpdate(registration);                  }                } else {                  // 首次缓存完成                  if (config &amp;&amp; config.onSuccess) {                    config.onSuccess(registration);                  }                }              }            };          };        })        .catch(error =&gt; {          console.error('Service Worker 注册错误:', error);        });    });  }}export function unregister() {  if ('serviceWorker' in navigator) {    navigator.serviceWorker.ready      .then(registration =&gt; {        registration.unregister();      })      .catch(error =&gt; {        console.error(error.message);      });  }}

React Hook 封装123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263// src/hooks/useServiceWorker.jsimport { useState, useEffect } from 'react';export function useServiceWorker() {  const [registration, setRegistration] = useState(null);  const [isOnline, setIsOnline] = useState(navigator.onLine);  const [updateAvailable, setUpdateAvailable] = useState(false);  const [waitingWorker, setWaitingWorker] = useState(null);    useEffect(() =&gt; {    // 注册 Service Worker    if ('serviceWorker' in navigator) {      navigator.serviceWorker.register('/sw.js')        .then(reg =&gt; {          setRegistration(reg);                    // 检查更新          reg.addEventListener('updatefound', () =&gt; {            const newWorker = reg.installing;                        newWorker.addEventListener('statechange', () =&gt; {              if (newWorker.state === 'installed' &amp;&amp; navigator.serviceWorker.controller) {                setUpdateAvailable(true);                setWaitingWorker(newWorker);              }            });          });        });    }        // 监听在线状态    const handleOnline = () =&gt; setIsOnline(true);    const handleOffline = () =&gt; setIsOnline(false);        window.addEventListener('online', handleOnline);    window.addEventListener('offline', handleOffline);        return () =&gt; {      window.removeEventListener('online', handleOnline);      window.removeEventListener('offline', handleOffline);    };  }, []);    // 应用更新  const applyUpdate = () =&gt; {    if (waitingWorker) {      waitingWorker.postMessage({ type: 'SKIP_WAITING' });            waitingWorker.addEventListener('statechange', e =&gt; {        if (e.target.state === 'activated') {          window.location.reload();        }      });    }  };    return {    registration,    isOnline,    updateAvailable,    applyUpdate  };}

更新提示组件12345678910111213141516171819202122232425262728// src/components/UpdatePrompt.jsximport React from 'react';import { useServiceWorker } from '../hooks/useServiceWorker';export function UpdatePrompt() {  const { updateAvailable, applyUpdate, isOnline } = useServiceWorker();    if (!updateAvailable) return null;    return (    &lt;div className="update-prompt"&gt;      &lt;p&gt;发现新版本!&lt;/p&gt;      &lt;button onClick={applyUpdate}&gt;立即更新&lt;/button&gt;    &lt;/div&gt;  );}// App.js 中使用import { UpdatePrompt } from './components/UpdatePrompt';function App() {  return (    &lt;div className="App"&gt;      &lt;UpdatePrompt /&gt;      {/* 其他内容 */}    &lt;/div&gt;  );}

离线状态指示器123456789101112131415// src/components/OfflineIndicator.jsximport React from 'react';import { useServiceWorker } from '../hooks/useServiceWorker';export function OfflineIndicator() {  const { isOnline } = useServiceWorker();    if (isOnline) return null;    return (    &lt;div className="offline-banner"&gt;      &lt;span&gt;⚠️ 您当前处于离线状态&lt;/span&gt;    &lt;/div&gt;  );}

Service Worker 通信123456789101112131415161718192021222324252627282930313233343536// src/utils/swMessage.jsexport function sendMessageToSW(message) {  return new Promise((resolve, reject) =&gt; {    const messageChannel = new MessageChannel();        messageChannel.port1.onmessage = event =&gt; {      if (event.data.error) {        reject(event.data.error);      } else {        resolve(event.data);      }    };        if (navigator.serviceWorker.controller) {      navigator.serviceWorker.controller.postMessage(message, [messageChannel.port2]);    } else {      reject(new Error('No active Service Worker'));    }  });}// 使用示例import { sendMessageToSW } from './utils/swMessage';function MyComponent() {  const handleClearCache = async () =&gt; {    try {      const result = await sendMessageToSW({ type: 'CLEAR_CACHE' });      console.log('缓存已清理:', result);    } catch (error) {      console.error('清理失败:', error);    }  };    return &lt;button onClick={handleClearCache}&gt;清理缓存&lt;/button&gt;;}

5. PWA 应用实践添加到主屏幕123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869// src/hooks/useInstallPrompt.jsimport { useState, useEffect } from 'react';export function useInstallPrompt() {  const [installPrompt, setInstallPrompt] = useState(null);  const [isInstalled, setIsInstalled] = useState(false);    useEffect(() =&gt; {    // 检查是否已安装    if (window.matchMedia('(display-mode: standalone)').matches) {      setIsInstalled(true);    }        // 监听安装提示事件    const handleBeforeInstallPrompt = (e) =&gt; {      e.preventDefault();      setInstallPrompt(e);    };        // 监听安装完成    const handleAppInstalled = () =&gt; {      setIsInstalled(true);      setInstallPrompt(null);    };        window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);    window.addEventListener('appinstalled', handleAppInstalled);        return () =&gt; {      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);      window.removeEventListener('appinstalled', handleAppInstalled);    };  }, []);    const promptInstall = async () =&gt; {    if (!installPrompt) return false;        installPrompt.prompt();    const { outcome } = await installPrompt.userChoice;        if (outcome === 'accepted') {      setInstallPrompt(null);      return true;    }        return false;  };    return { canInstall: !!installPrompt, isInstalled, promptInstall };}// 安装按钮组件import { useInstallPrompt } from '../hooks/useInstallPrompt';function InstallButton() {  const { canInstall, isInstalled, promptInstall } = useInstallPrompt();    if (isInstalled) {    return &lt;div&gt;✓ 已安装到桌面&lt;/div&gt;;  }    if (!canInstall) return null;    return (    &lt;button onClick={promptInstall} className="install-btn"&gt;      📱 安装应用    &lt;/button&gt;  );}

Manifest 配置12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849// public/manifest.json{  "name": "My React PWA",  "short_name": "React PWA",  "description": "一个功能完整的 PWA 应用",  "start_url": "/",  "display": "standalone",  "theme_color": "#000000",  "background_color": "#ffffff",  "orientation": "portrait",  "icons": [    {      "src": "/icons/icon-72x72.png",      "sizes": "72x72",      "type": "image/png",      "purpose": "maskable any"    },    {      "src": "/icons/icon-96x96.png",      "sizes": "96x96",      "type": "image/png",      "purpose": "maskable any"    },    {      "src": "/icons/icon-128x128.png",      "sizes": "128x128",      "type": "image/png",      "purpose": "maskable any"    },    {      "src": "/icons/icon-144x144.png",      "sizes": "144x144",      "type": "image/png",      "purpose": "maskable any"    },    {      "src": "/icons/icon-192x192.png",      "sizes": "192x192",      "type": "image/png",      "purpose": "maskable any"    },    {      "src": "/icons/icon-512x512.png",      "sizes": "512x512",      "type": "image/png",      "purpose": "maskable any"    }  ]}

推送通知实现 public/sw.js - 接收推送self.addEventListener('push', event =&gt; {  const data = event.data ? event.data.json() : {};    const options = {    body: data.body || '您有新的消息',    icon: '/icons/icon-192x192.png',    badge: '/icons/badge-72x72.png',    data: {      url: data.url || '/',      timestamp: Date.now()    },    actions: [      { action: 'open', title: '查看' },      { action: 'close', title: '关闭' }    ],    tag: data.tag || 'default',    renotify: true,    vibrate: [200, 100, 200]  };    event.waitUntil(    self.registration.showNotification(data.title || '新通知', options)  );});// 处理通知点击self.addEventListener('notificationclick', event =&gt; {  event.notification.close();    if (event.action === 'open' || !event.action) {    const urlToOpen = event.notification.data.url;        event.waitUntil(      clients.matchAll({ type: 'window', includeUncontrolled: true })        .then(windowClients =&gt; {          // 查找已打开的窗口          for (let client of windowClients) {            if (client.url === urlToOpen &amp;&amp; 'focus' in client) {              return client.focus();            }          }          // 打开新窗口          if (clients.openWindow) {            return clients.openWindow(urlToOpen);          }        })    );  }});// React 组件 - 订阅推送import { useState, useEffect } from 'react';function PushNotification() {  const [subscription, setSubscription] = useState(null);  const [permission, setPermission] = useState(Notification.permission);    useEffect(() =&gt; {    if ('serviceWorker' in navigator &amp;&amp; 'PushManager' in window) {      navigator.serviceWorker.ready.then(registration =&gt; {        registration.pushManager.getSubscription()          .then(sub =&gt; setSubscription(sub));      });    }  }, []);    const requestPermission = async () =&gt; {    const result = await Notification.requestPermission();    setPermission(result);    return result === 'granted';  };    const subscribeToPush = async () =&gt; {    try {      const hasPermission = await requestPermission();      if (!hasPermission) return;            const registration = await navigator.serviceWorker.ready;            const subscription = await registration.pushManager.subscribe({        userVisibleOnly: true,        applicationServerKey: urlBase64ToUint8Array(process.env.REACT_APP_VAPID_PUBLIC_KEY)      });            // 发送订阅信息到服务器      await fetch('/api/push/subscribe', {        method: 'POST',        headers: { 'Content-Type': 'application/json' },        body: JSON.stringify(subscription)      });            setSubscription(subscription);    } catch (error) {      console.error('订阅失败:', error);    }  };    const unsubscribeFromPush = async () =&gt; {    if (subscription) {      await subscription.unsubscribe();            await fetch('/api/push/unsubscribe', {        method: 'POST',        headers: { 'Content-Type': 'application/json' },        body: JSON.stringify({ endpoint: subscription.endpoint })      });            setSubscription(null);    }  };    return (    &lt;div&gt;      &lt;h3&gt;推送通知&lt;/h3&gt;      {permission === 'denied' &amp;&amp; &lt;p&gt;通知权限已被拒绝&lt;/p&gt;}      {permission === 'default' &amp;&amp; (        &lt;button onClick={requestPermission}&gt;请求通知权限&lt;/button&gt;      )}      {permission === 'granted' &amp;&amp; (        subscription ? (          &lt;button onClick={unsubscribeFromPush}&gt;取消订阅&lt;/button&gt;        ) : (          &lt;button onClick={subscribeToPush}&gt;订阅推送&lt;/button&gt;        )      )}    &lt;/div&gt;  );}// 辅助函数function urlBase64ToUint8Array(base64String) {  const padding = '='.repeat((4 - base64String.length % 4) % 4);  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');  const rawData = window.atob(base64);  const outputArray = new Uint8Array(rawData.length);    for (let i = 0; i &lt; rawData.length; ++i) {    outputArray[i] = rawData.charCodeAt(i);  }  return outputArray;}

后台同步1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071727374// public/sw.js - 后台同步self.addEventListener('sync', event =&gt; {  if (event.tag === 'sync-posts') {    event.waitUntil(syncPosts());  }});async function syncPosts() {  try {    // 获取离线期间保存的数据    const db = await openDB();    const pendingPosts = await db.getAll('pending-posts');        // 批量上传    for (const post of pendingPosts) {      const response = await fetch('/api/posts', {        method: 'POST',        headers: { 'Content-Type': 'application/json' },        body: JSON.stringify(post)      });            if (response.ok) {        await db.delete('pending-posts', post.id);      }    }        // 通知用户    await self.registration.showNotification('同步完成', {      body: `成功同步 ${pendingPosts.length} 条数据`,      icon: '/icons/icon-192x192.png'    });  } catch (error) {    console.error('同步失败:', error);    throw error; // 重新抛出错误以便重试  }}// React 组件 - 触发后台同步function OfflinePost() {  const [isOnline, setIsOnline] = useState(navigator.onLine);    const handleSubmit = async (postData) =&gt; {    if (isOnline) {      // 在线直接提交      await fetch('/api/posts', {        method: 'POST',        body: JSON.stringify(postData)      });    } else {      // 离线保存到 IndexedDB      const db = await openDB();      await db.add('pending-posts', { ...postData, id: Date.now() });            // 注册后台同步      if ('serviceWorker' in navigator &amp;&amp; 'SyncManager' in window) {        const registration = await navigator.serviceWorker.ready;        await registration.sync.register('sync-posts');        alert('数据已保存,将在网络恢复后自动同步');      }    }  };    return (    &lt;form onSubmit={(e) =&gt; {      e.preventDefault();      handleSubmit({ title: e.target.title.value, content: e.target.content.value });    }}&gt;      {!isOnline &amp;&amp; &lt;div className="offline-tip"&gt;离线模式:数据将在联网后同步&lt;/div&gt;}      &lt;input name="title" placeholder="标题" required /&gt;      &lt;textarea name="content" placeholder="内容" required /&gt;      &lt;button type="submit"&gt;发布&lt;/button&gt;    &lt;/form&gt;  );}

离线页面123456789101112131415161718192021222324// public/sw.js - 离线页面const OFFLINE_PAGE = '/offline.html';// 安装时缓存离线页面self.addEventListener('install', event =&gt; {  event.waitUntil(    caches.open('offline').then(cache =&gt; {      return cache.add(OFFLINE_PAGE);    })  );});// 拦截导航请求self.addEventListener('fetch', event =&gt; {  if (event.request.mode === 'navigate') {    event.respondWith(      fetch(event.request).catch(() =&gt; {        return caches.match(OFFLINE_PAGE);      })    );  }});// 创建 public/offline.html

1234567891011121314151617181920212223242526272829303132333435363738&lt;!DOCTYPE html&gt;&lt;html lang="zh-CN"&gt;&lt;head&gt;  &lt;meta charset="UTF-8"&gt;  &lt;meta name="viewport" content="width=device-width, initial-scale=1.0"&gt;  &lt;title&gt;离线模式&lt;/title&gt;  &lt;style&gt;    body {      display: flex;      flex-direction: column;      align-items: center;      justify-content: center;      height: 100vh;      margin: 0;      font-family: sans-serif;      background: #f5f5f5;    }    .offline-icon { font-size: 4rem; }    h1 { color: #333; }    p { color: #666; }    .retry-btn {      margin-top: 2rem;      padding: 0.75rem 2rem;      background: #007bff;      color: white;      border: none;      border-radius: 4px;      cursor: pointer;    }  &lt;/style&gt;&lt;/head&gt;&lt;body&gt;  &lt;div class="offline-icon"&gt;📡&lt;/div&gt;  &lt;h1&gt;您当前处于离线状态&lt;/h1&gt;  &lt;p&gt;请检查网络连接后重试&lt;/p&gt;  &lt;button class="retry-btn" onclick="location.reload()"&gt;重新加载&lt;/button&gt;&lt;/body&gt;&lt;/html&gt;

6. 使用 Workbox 简化开发Workbox 基础配置123456789101112131415161718192021222324252627282930313233343536373839404142434445464748// 安装 Workbox// npm install workbox-webpack-plugin --save-dev// webpack.config.js (或 CRA 使用 craco)const { GenerateSW } = require('workbox-webpack-plugin');module.exports = {  // ...其他配置  plugins: [    new GenerateSW({      clientsClaim: true,      skipWaiting: true,      maximumFileSizeToCacheInBytes: 5 * 1024 * 1024, // 5MB      runtimeCaching: [        {          urlPattern: /^https:\/\/api\.example\.com/,          handler: 'NetworkFirst',          options: {            cacheName: 'api-cache',            expiration: {              maxEntries: 50,              maxAgeSeconds: 5 * 60 // 5 分钟            },            networkTimeoutSeconds: 10          }        },        {          urlPattern: /\.(?:png|jpg|jpeg|svg|gif)$/,          handler: 'CacheFirst',          options: {            cacheName: 'image-cache',            expiration: {              maxEntries: 100,              maxAgeSeconds: 30 * 24 * 60 * 60 // 30 天            }          }        },        {          urlPattern: /\.(?:js|css)$/,          handler: 'StaleWhileRevalidate',          options: {            cacheName: 'static-resources'          }        }      ]    })  ]};

自定义 Service Worker (使用 InjectManifest)123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990// webpack.config.jsconst { InjectManifest } = require('workbox-webpack-plugin');module.exports = {  plugins: [    new InjectManifest({      swSrc: './src/sw.js',      swDest: 'service-worker.js',      maximumFileSizeToCacheInBytes: 5 * 1024 * 1024    })  ]};// src/sw.jsimport { precacheAndRoute } from 'workbox-precaching';import { registerRoute } from 'workbox-routing';import { NetworkFirst, CacheFirst, StaleWhileRevalidate } from 'workbox-strategies';import { ExpirationPlugin } from 'workbox-expiration';import { CacheableResponsePlugin } from 'workbox-cacheable-response';// 预缓存构建时生成的资源列表precacheAndRoute(self.__WB_MANIFEST);// API 请求 - 网络优先registerRoute(  ({ url }) =&gt; url.pathname.startsWith('/api/'),  new NetworkFirst({    cacheName: 'api-cache',    plugins: [      new ExpirationPlugin({        maxEntries: 50,        maxAgeSeconds: 5 * 60      }),      new CacheableResponsePlugin({        statuses: [0, 200]      })    ]  }));// 图片 - 缓存优先registerRoute(  ({ request }) =&gt; request.destination === 'image',  new CacheFirst({    cacheName: 'images',    plugins: [      new ExpirationPlugin({        maxEntries: 100,        maxAgeSeconds: 30 * 24 * 60 * 60      })    ]  }));// 字体 - 缓存优先registerRoute(  ({ request }) =&gt; request.destination === 'font',  new CacheFirst({    cacheName: 'fonts',    plugins: [      new ExpirationPlugin({        maxEntries: 20,        maxAgeSeconds: 365 * 24 * 60 * 60      })    ]  }));// Google Fonts - 过期重验证registerRoute(  ({ url }) =&gt; url.origin === 'https://fonts.googleapis.com',  new StaleWhileRevalidate({    cacheName: 'google-fonts-stylesheets'  }));registerRoute(  ({ url }) =&gt; url.origin === 'https://fonts.gstatic.com',  new CacheFirst({    cacheName: 'google-fonts-webfonts',    plugins: [      new CacheableResponsePlugin({        statuses: [0, 200]      }),      new ExpirationPlugin({        maxAgeSeconds: 365 * 24 * 60 * 60      })    ]  }));

Workbox 插件使用1234567891011121314151617181920212223242526272829303132333435import { BackgroundSyncPlugin } from 'workbox-background-sync';import { BroadcastUpdatePlugin } from 'workbox-broadcast-update';// 后台同步插件const bgSyncPlugin = new BackgroundSyncPlugin('api-queue', {  maxRetentionTime: 24 * 60 // 重试 24 小时});registerRoute(  ({ url }) =&gt; url.pathname.startsWith('/api/posts'),  new NetworkOnly({    plugins: [bgSyncPlugin]  }),  'POST');// 广播更新插件const broadcastPlugin = new BroadcastUpdatePlugin({  channelName: 'content-updates',  headersToCheck: ['etag', 'last-modified']});registerRoute(  '/api/content',  new StaleWhileRevalidate({    plugins: [broadcastPlugin]  }));// 在页面中监听更新const channel = new BroadcastChannel('content-updates');channel.addEventListener('message', event =&gt; {  console.log('内容已更新:', event.data);  // 提示用户刷新});

7. 性能优化与最佳实践缓存版本管理12345678910111213141516171819202122// 使用语义化版本const VERSION = '1.2.3';const CACHE_NAME = `my-app-v${VERSION}`;// 或使用构建哈希const CACHE_NAME = `my-app-${__BUILD_HASH__}`;// 清理旧缓存self.addEventListener('activate', event =&gt; {  event.waitUntil(    caches.keys().then(cacheNames =&gt; {      return Promise.all(        cacheNames          .filter(name =&gt; name.startsWith('my-app-') &amp;&amp; name !== CACHE_NAME)          .map(name =&gt; {            console.log('删除旧缓存:', name);            return caches.delete(name);          })      );    })  );});

预缓存关键资源123456789101112131415const CRITICAL_ASSETS = [  '/',  '/index.html',  '/static/css/main.css',  '/static/js/main.js',  '/manifest.json'];self.addEventListener('install', event =&gt; {  event.waitUntil(    caches.open(CACHE_NAME).then(cache =&gt; {      return cache.addAll(CRITICAL_ASSETS);    }).then(() =&gt; self.skipWaiting())  );});

缓存大小限制12345678910111213141516171819202122232425262728293031323334353637383940class CacheManager {  constructor(cacheName, maxItems = 50, maxAge = 7 * 24 * 60 * 60 * 1000) {    this.cacheName = cacheName;    this.maxItems = maxItems;    this.maxAge = maxAge;  }    async cleanUp() {    const cache = await caches.open(this.cacheName);    const requests = await cache.keys();        // 按时间戳排序    const entries = await Promise.all(      requests.map(async request =&gt; {        const response = await cache.match(request);        const date = new Date(response.headers.get('date')).getTime();        return { request, date };      })    );        entries.sort((a, b) =&gt; b.date - a.date);        // 删除过期和超量的缓存    const now = Date.now();    for (let i = 0; i &lt; entries.length; i++) {      if (i &gt;= this.maxItems || now - entries[i].date &gt; this.maxAge) {        await cache.delete(entries[i].request);      }    }  }}// 定期清理const cacheManager = new CacheManager('dynamic-cache', 100);self.addEventListener('message', event =&gt; {  if (event.data.type === 'CLEANUP_CACHE') {    event.waitUntil(cacheManager.cleanUp());  }});

请求优先级12345678910111213141516171819202122232425self.addEventListener('fetch', event =&gt; {  const { request } = event;  const url = new URL(request.url);    // 高优先级:文档和关键资源  if (request.mode === 'navigate' || request.destination === 'style') {    event.respondWith(networkFirst(request));    return;  }    // 中优先级:脚本和字体  if (request.destination === 'script' || request.destination === 'font') {    event.respondWith(cacheFirst(request));    return;  }    // 低优先级:图片  if (request.destination === 'image') {    event.respondWith(cacheFirst(request, { timeout: 5000 }));    return;  }    // 默认策略  event.respondWith(fetch(request));});

渐进式加载1234567891011121314151617181920212223242526// 分层缓存策略const CACHE_TIERS = {  critical: 'critical-v1',    // App Shell  primary: 'primary-v1',      // 核心功能  secondary: 'secondary-v1',  // 次要功能  media: 'media-v1'           // 媒体资源};self.addEventListener('install', event =&gt; {  event.waitUntil(    Promise.all([      // 优先缓存关键资源      caches.open(CACHE_TIERS.critical).then(cache =&gt;         cache.addAll(['/index.html', '/app.js', '/app.css'])      ),      // 延迟缓存次要资源      new Promise(resolve =&gt; {        setTimeout(() =&gt; {          caches.open(CACHE_TIERS.secondary).then(cache =&gt;            cache.addAll(['/about.html', '/help.html'])          ).then(resolve);        }, 1000);      })    ])  );});

8. 调试与监控Chrome DevTools 调试12345678910111213141516171819202122// 添加调试日志const DEBUG = true;function log(...args) {  if (DEBUG) {    console.log('[SW]', ...args);  }}self.addEventListener('install', event =&gt; {  log('安装事件', event);});self.addEventListener('fetch', event =&gt; {  log('请求:', event.request.url);});// 在控制台查看 Service Worker 状态// chrome://serviceworker-internals/// 清除所有 Service Worker// self.registration.unregister()

错误处理12345678910111213141516171819202122232425262728293031323334353637// 全局错误捕获self.addEventListener('error', event =&gt; {  console.error('Service Worker 错误:', event.error);    // 上报错误  fetch('/api/error-log', {    method: 'POST',    body: JSON.stringify({      message: event.error.message,      stack: event.error.stack,      timestamp: Date.now()    })  }).catch(() =&gt; {    // 忽略上报失败  });});// Promise 拒绝处理self.addEventListener('unhandledrejection', event =&gt; {  console.error('未处理的 Promise 拒绝:', event.reason);});// 安全的 fetch 包装async function safeFetch(request) {  try {    const response = await fetch(request);    if (!response.ok) {      throw new Error(`HTTP error! status: ${response.status}`);    }    return response;  } catch (error) {    console.error('请求失败:', request.url, error);        // 返回离线页面或占位符    return caches.match('/offline.html');  }}

性能监控123456789101112131415161718192021222324252627282930313233343536373839404142// 记录缓存命中率let cacheHits = 0;let cacheMisses = 0;self.addEventListener('fetch', event =&gt; {  event.respondWith(    caches.match(event.request).then(response =&gt; {      if (response) {        cacheHits++;        return response;      }            cacheMisses++;      return fetch(event.request);    })  );});// 定期上报统计setInterval(() =&gt; {  const total = cacheHits + cacheMisses;  if (total &gt; 0) {    const hitRate = (cacheHits / total * 100).toFixed(2);    console.log(`缓存命中率: ${hitRate}%`);        // 上报到分析服务    self.clients.matchAll().then(clients =&gt; {      clients.forEach(client =&gt; {        client.postMessage({          type: 'CACHE_STATS',          hits: cacheHits,          misses: cacheMisses,          hitRate        });      });    });        // 重置计数器    cacheHits = 0;    cacheMisses = 0;  }}, 60000); // 每分钟

9. 常见问题与解决方案Service Worker 不更新12345678910111213141516171819202122// 解决方案 1: 强制更新navigator.serviceWorker.register('/sw.js').then(registration =&gt; {  // 开发环境强制更新  if (process.env.NODE_ENV === 'development') {    registration.update();  }});// 解决方案 2: 在 sw.js 中self.addEventListener('install', event =&gt; {  // 跳过等待,立即激活  self.skipWaiting();});self.addEventListener('activate', event =&gt; {  // 立即接管所有页面  event.waitUntil(self.clients.claim());});// 解决方案 3: 禁用浏览器缓存// 在服务器配置 sw.js 的响应头// Cache-Control: no-cache, no-store, must-revalidate

CORS 问题1234567891011121314151617// 处理跨域请求self.addEventListener('fetch', event =&gt; {  const { request } = event;    // 跨域请求使用 no-cors 模式  if (request.mode === 'no-cors') {    event.respondWith(      fetch(request).catch(() =&gt; {        return new Response('', { status: 200, statusText: 'OK' });      })    );    return;  }    // 正常请求  event.respondWith(fetch(request));});

IndexedDB 使用1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556// 封装 IndexedDB 操作class DBHelper {  constructor(dbName, version = 1) {    this.dbName = dbName;    this.version = version;  }    open(storeName) {    return new Promise((resolve, reject) =&gt; {      const request = indexedDB.open(this.dbName, this.version);            request.onerror = () =&gt; reject(request.error);      request.onsuccess = () =&gt; resolve(request.result);            request.onupgradeneeded = event =&gt; {        const db = event.target.result;        if (!db.objectStoreNames.contains(storeName)) {          db.createObjectStore(storeName, { keyPath: 'id', autoIncrement: true });        }      };    });  }    async add(storeName, data) {    const db = await this.open(storeName);    return new Promise((resolve, reject) =&gt; {      const transaction = db.transaction(storeName, 'readwrite');      const store = transaction.objectStore(storeName);      const request = store.add(data);            request.onsuccess = () =&gt; resolve(request.result);      request.onerror = () =&gt; reject(request.error);    });  }    async getAll(storeName) {    const db = await this.open(storeName);    return new Promise((resolve, reject) =&gt; {      const transaction = db.transaction(storeName, 'readonly');      const store = transaction.objectStore(storeName);      const request = store.getAll();            request.onsuccess = () =&gt; resolve(request.result);      request.onerror = () =&gt; reject(request.error);    });  }}// 使用示例const db = new DBHelper('my-app', 1);// 保存离线数据await db.add('pending-posts', { title: 'Test', content: 'Content' });// 获取待同步数据const pendingPosts = await db.getAll('pending-posts');

10. 总结Service Worker 作为 PWA 的核心技术,为 Web 应用带来了:
关键能力
离线访问:通过缓存策略实现完全离线体验
性能优化:减少网络请求,加快资源加载
后台处理:推送通知、后台同步等高级功能
版本控制:灵活的更新和回退机制

最佳实践
渐进增强:从简单的缓存开始,逐步添加高级功能
分层缓存:根据资源重要性和更新频率选择策略
版本管理:使用语义化版本,及时清理旧缓存
错误处理:完善的错误捕获和降级方案
性能监控:跟踪缓存命中率和资源加载时间

在 React 中的应用
使用 Workbox 简化配置和管理
封装 Hook 处理注册和更新逻辑
结合 React 组件提供用户友好的交互
与状态管理库集成实现离线数据同步

注意事项
始终在 HTTPS 环境下部署(生产环境)
谨慎处理缓存策略,避免用户看到过期内容
提供清晰的更新提示和离线状态指示
定期清理缓存,避免占用过多存储空间
充分测试各种网络状况下的应用表现

通过合理使用 Service Worker,可以将 Web 应用打造成媲美原生应用的高性能 PWA,为用户提供流畅、可靠的体验。

React Query 源码解析：异步状态管理的底层实现一、React Query 核心概念为什么需要 React Query？在传统的 React 开发中，处理服务端数据需要手动管理：
123456789101112131415161718192021222324// 传统方式：手动管理异步状态function UserList() {  const [data, setData] = useState(null);  const [loading, setLoading] = useState(false);  const [error, setError] = useState(null);    useEffect(() =&gt; {    setLoading(true);    fetch('/api/users')      .then(res =&gt; res.json())      .then(data =&gt; {        setData(data);        setLoading(false);      })      .catch(err =&gt; {        setError(err);        setLoading(false);      });  }, []);    if (loading) return &lt;div&gt;Loading...&lt;/div&gt;;  if (error) return &lt;div&gt;Error: {error.message}&lt;/div&gt;;  return &lt;div&gt;{/* 渲染数据 */}&lt;/div&gt;;}

这种方式存在诸多问题：

样板代码多：每个请求都要写一遍 loading、error 状态
无缓存机制：重复请求相同数据
无自动重试：失败后需要手动处理
数据过期问题：不知道何时重新获取数据

React Query 优雅地解决了这些问题：
1234567891011// React Query 方式function UserList() {  const { data, isLoading, error } = useQuery({    queryKey: ['users'],    queryFn: () =&gt; fetch('/api/users').then(res =&gt; res.json()),  });    if (isLoading) return &lt;div&gt;Loading...&lt;/div&gt;;  if (error) return &lt;div&gt;Error: {error.message}&lt;/div&gt;;  return &lt;div&gt;{/* 渲染数据 */}&lt;/div&gt;;}

核心特性
自动缓存：相同查询自动使用缓存
后台自动重新获取：保持数据新鲜
请求去重：相同请求只发一次
乐观更新：立即更新 UI，后台同步
分页和无限滚动：内置支持
离线支持：网络恢复后自动同步

二、核心架构设计整体架构React Query 的核心架构包含几个关键部分：
1234567891011121314151617181920┌─────────────────────────────────────────┐│           QueryClient                   ││  ┌─────────────────────────────────┐   ││  │       QueryCache                │   ││  │  ┌──────────┐  ┌──────────┐    │   ││  │  │ Query 1  │  │ Query 2  │... │   ││  │  └──────────┘  └──────────┘    │   ││  └─────────────────────────────────┘   ││  ┌─────────────────────────────────┐   ││  │      MutationCache              │   ││  │  ┌──────────┐  ┌──────────┐    │   ││  │  │Mutation 1│  │Mutation 2│... │   ││  │  └──────────┘  └──────────┘    │   ││  └─────────────────────────────────┘   │└─────────────────────────────────────────┘           ↕    ┌──────────────┐    │  useQuery    │    │  useMutation │    └──────────────┘

核心类和概念
QueryClient：管理所有查询和变更的客户端
QueryCache：存储所有查询实例
Query：单个查询实例，包含数据、状态、配置
MutationCache：存储所有变更实例
Mutation：单个变更操作

三、QueryClient 实现基础结构12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455// 简化版 QueryClient 实现class QueryClient {  constructor(config = {}) {    this.queryCache = new QueryCache();    this.mutationCache = new MutationCache();    this.defaultOptions = config.defaultOptions || {};    this.queryDefaults = [];    this.mutationDefaults = [];  }    // 获取 QueryCache  getQueryCache() {    return this.queryCache;  }    // 获取 MutationCache  getMutationCache() {    return this.mutationCache;  }    // 使查询失效  invalidateQueries(filters) {    return this.queryCache.findAll(filters).forEach((query) =&gt; {      query.invalidate();    });  }    // 手动设置查询数据  setQueryData(queryKey, updater) {    const query = this.queryCache.find(queryKey);    if (!query) {      return this.queryCache.build(this, {        queryKey,        queryFn: () =&gt; updater,      }).fetch();    }    return query.setData(updater);  }    // 获取查询数据  getQueryData(queryKey) {    return this.queryCache.find(queryKey)?.state.data;  }    // 预取数据  prefetchQuery(options) {    return this.fetchQuery(options).catch(() =&gt; {});  }    // 获取数据  async fetchQuery(options) {    const query = this.queryCache.build(this, options);    return query.fetch();  }}

QueryCache 实现12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970717273747576777879808182838485868788class QueryCache {  constructor() {    this.queries = []; // 存储所有查询    this.queriesMap = {}; // queryKey -&gt; Query 的映射  }    // 构建查询  build(client, options) {    const queryKey = options.queryKey;    const queryHash = hashQueryKey(queryKey);        let query = this.queriesMap[queryHash];        if (!query) {      query = new Query({        cache: this,        queryKey,        queryHash,        options: client.defaultQueryOptions(options),      });            this.queries.push(query);      this.queriesMap[queryHash] = query;            // 通知订阅者      this.notify({ type: 'added', query });    }        return query;  }    // 查找查询  find(queryKey) {    const queryHash = hashQueryKey(queryKey);    return this.queriesMap[queryHash];  }    // 查找所有匹配的查询  findAll(filters = {}) {    return this.queries.filter((query) =&gt; {      return matchQuery(filters, query);    });  }    // 移除查询  remove(query) {    const index = this.queries.indexOf(query);    if (index !== -1) {      this.queries.splice(index, 1);      delete this.queriesMap[query.queryHash];      this.notify({ type: 'removed', query });    }  }    // 清空所有查询  clear() {    this.queries.forEach((query) =&gt; {      query.destroy();    });    this.queries = [];    this.queriesMap = {};  }}// 生成查询键的哈希function hashQueryKey(queryKey) {  return JSON.stringify(queryKey);}// 匹配查询function matchQuery(filters, query) {  const { queryKey, exact } = filters;    if (queryKey) {    if (exact) {      return query.queryHash === hashQueryKey(queryKey);    }    return partialMatchKey(query.queryKey, queryKey);  }    return true;}// 部分匹配 queryKeyfunction partialMatchKey(a, b) {  return a === b || (Array.isArray(a) &amp;&amp; Array.isArray(b) &amp;&amp;     b.every((item, index) =&gt; a[index] === item));}

四、Query 核心实现Query 类 Query {  constructor(config) {    this.cache = config.cache;    this.queryKey = config.queryKey;    this.queryHash = config.queryHash;    this.options = config.options;        // 初始状态    this.state = {      data: undefined,      dataUpdatedAt: 0,      error: null,      errorUpdatedAt: 0,      fetchStatus: 'idle', // idle, fetching, paused      status: 'loading', // loading, error, success      isInvalidated: false,    };        this.observers = []; // 观察者列表    this.gcTimeout = null; // 垃圾回收定时器    this.abortSignalConsumed = false;  }    // 订阅查询  subscribe(observer) {    this.observers.push(observer);        // 取消垃圾回收    this.clearGcTimeout();        // 返回取消订阅函数    return () =&gt; {      this.observers = this.observers.filter((o) =&gt; o !== observer);            // 如果没有观察者了，开始垃圾回收倒计时      if (!this.observers.length) {        this.scheduleGc();      }    };  }    // 安排垃圾回收  scheduleGc() {    this.clearGcTimeout();        const cacheTime = this.options.cacheTime || 5 * 60 * 1000;        this.gcTimeout = setTimeout(() =&gt; {      this.cache.remove(this);    }, cacheTime);  }    // 清除垃圾回收  clearGcTimeout() {    if (this.gcTimeout) {      clearTimeout(this.gcTimeout);      this.gcTimeout = null;    }  }    // 使查询失效  invalidate() {    if (!this.state.isInvalidated) {      this.state.isInvalidated = true;      this.notify();            // 如果有活跃的观察者，立即重新获取      if (this.observers.length) {        this.fetch();      }    }  }    // 设置数据  setData(updater) {    const prevData = this.state.data;    const data = typeof updater === 'function'       ? updater(prevData)       : updater;        if (data !== prevData) {      this.state = {        ...this.state,        data,        dataUpdatedAt: Date.now(),        error: null,        isInvalidated: false,        status: 'success',      };            this.notify();    }        return data;  }    // 获取数据  async fetch(options = {}) {    // 如果正在获取，返回现有的 Promise    if (this.promise) {      return this.promise;    }        // 更新状态为 fetching    this.state = {      ...this.state,      fetchStatus: 'fetching',    };    this.notify();        // 创建 AbortController    const abortController = new AbortController();        try {      // 执行查询函数      this.promise = Promise.resolve(        this.options.queryFn({          queryKey: this.queryKey,          signal: abortController.signal,        })      );            const data = await this.promise;            // 更新成功状态      this.state = {        ...this.state,        data,        dataUpdatedAt: Date.now(),        error: null,        errorUpdatedAt: 0,        fetchStatus: 'idle',        status: 'success',        isInvalidated: false,      };            this.notify();      return data;          } catch (error) {      // 更新错误状态      this.state = {        ...this.state,        error,        errorUpdatedAt: Date.now(),        fetchStatus: 'idle',        status: 'error',      };            this.notify();      throw error;          } finally {      this.promise = null;    }  }    // 通知所有观察者  notify() {    this.observers.forEach((observer) =&gt; {      observer.notify();    });  }    // 销毁查询  destroy() {    this.clearGcTimeout();    this.observers = [];  }}

五、useQuery Hook 实现核心实现123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081import { useEffect, useReducer, useRef } from 'react';import { useQueryClient } from './QueryClientProvider';function useQuery(options) {  const client = useQueryClient();  const [, forceUpdate] = useReducer((x) =&gt; x + 1, 0);    // 使用 ref 保存最新的配置  const optionsRef = useRef(options);  optionsRef.current = options;    // 获取或创建查询  const queryRef = useRef();  if (!queryRef.current) {    queryRef.current = client.getQueryCache().build(client, options);  }    const query = queryRef.current;    // 创建观察者  const observerRef = useRef();  if (!observerRef.current) {    observerRef.current = new QueryObserver(query, {      notify: forceUpdate,    });  }    const observer = observerRef.current;    // 订阅查询变化  useEffect(() =&gt; {    const unsubscribe = query.subscribe(observer);    return unsubscribe;  }, [query, observer]);    // 自动获取数据  useEffect(() =&gt; {    // 检查是否需要获取数据    const shouldFetch =       optionsRef.current.enabled !== false &amp;&amp;      query.state.fetchStatus === 'idle' &amp;&amp;      (query.state.isInvalidated ||        !query.state.dataUpdatedAt ||       isStale(query));        if (shouldFetch) {      query.fetch();    }  }, [query]);    // 窗口聚焦时重新获取  useEffect(() =&gt; {    if (optionsRef.current.refetchOnWindowFocus !== false) {      const handleFocus = () =&gt; {        if (document.visibilityState === 'visible') {          query.fetch();        }      };            window.addEventListener('visibilitychange', handleFocus);      return () =&gt; window.removeEventListener('visibilitychange', handleFocus);    }  }, [query]);    // 返回查询结果  return {    data: query.state.data,    error: query.state.error,    isLoading: query.state.status === 'loading',    isError: query.state.status === 'error',    isSuccess: query.state.status === 'success',    isFetching: query.state.fetchStatus === 'fetching',    refetch: () =&gt; query.fetch(),  };}// 判断数据是否过期function isStale(query) {  const staleTime = query.options.staleTime || 0;  return Date.now() - query.state.dataUpdatedAt &gt; staleTime;}

QueryObserver12345678910111213141516171819202122232425262728293031323334353637class QueryObserver {  constructor(query, options) {    this.query = query;    this.options = options;    this.currentResult = this.createResult();  }    // 创建结果对象  createResult() {    return {      data: this.query.state.data,      error: this.query.state.error,      isLoading: this.query.state.status === 'loading',      isError: this.query.state.status === 'error',      isSuccess: this.query.state.status === 'success',      isFetching: this.query.state.fetchStatus === 'fetching',    };  }    // 查询更新时的回调  notify() {    const nextResult = this.createResult();        // 检查结果是否真的变化了    if (this.hasResultChanged(nextResult)) {      this.currentResult = nextResult;      this.options.notify();    }  }    // 检查结果是否变化  hasResultChanged(result) {    return Object.keys(result).some((key) =&gt; {      return result[key] !== this.currentResult[key];    });  }}

六、缓存机制详解缓存层级React Query 的缓存分为几个层级：

内存缓存：默认的缓存位置
持久化缓存：可选的 localStorage/sessionStorage
初始数据：SSR 或预取的数据

缓存配置1234567891011121314151617const queryClient = new QueryClient({  defaultOptions: {    queries: {      // 数据新鲜时间（在此期间不会重新获取）      staleTime: 5 * 60 * 1000, // 5 分钟            // 缓存时间（无订阅者后多久删除）      cacheTime: 10 * 60 * 1000, // 10 分钟            // 失败后重试次数      retry: 3,            // 重试延迟      retryDelay: (attemptIndex) =&gt; Math.min(1000 * 2 ** attemptIndex, 30000),    },  },});

缓存失效策略1234567891011121314151617// 1. 时间失效useQuery({  queryKey: ['user', id],  queryFn: fetchUser,  staleTime: 60000, // 1 分钟内认为数据是新鲜的});// 2. 手动失效queryClient.invalidateQueries({ queryKey: ['users'] });// 3. 自动失效（mutation 后）const mutation = useMutation({  mutationFn: updateUser,  onSuccess: () =&gt; {    queryClient.invalidateQueries({ queryKey: ['users'] });  },});

缓存更新策略123456789101112131415161718192021222324252627282930313233// 1. 设置查询数据queryClient.setQueryData(['user', 1], (oldData) =&gt; ({  ...oldData,  name: 'New Name',}));// 2. 乐观更新const mutation = useMutation({  mutationFn: updateUser,    onMutate: async (newUser) =&gt; {    // 取消相关查询    await queryClient.cancelQueries({ queryKey: ['user', newUser.id] });        // 保存之前的数据    const previousUser = queryClient.getQueryData(['user', newUser.id]);        // 乐观更新    queryClient.setQueryData(['user', newUser.id], newUser);        return { previousUser };  },    onError: (err, newUser, context) =&gt; {    // 回滚    queryClient.setQueryData(['user', newUser.id], context.previousUser);  },    onSettled: (data, error, variables) =&gt; {    // 重新获取    queryClient.invalidateQueries({ queryKey: ['user', variables.id] });  },});

七、请求去重机制实现原理12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455class Query {  constructor(config) {    // ...    this.promise = null; // 存储当前的请求 Promise  }    async fetch(options = {}) {    // 如果已有请求在进行，直接返回现有的 Promise    if (this.promise) {      console.log('Deduping request for', this.queryKey);      return this.promise;    }        // 创建新的请求    this.state.fetchStatus = 'fetching';    this.notify();        this.promise = Promise.resolve(      this.options.queryFn({        queryKey: this.queryKey,      })    );        try {      const data = await this.promise;      this.setData(data);      return data;    } catch (error) {      this.state.error = error;      throw error;    } finally {      this.promise = null;    }  }}// 测试请求去重function App() {  // 这三个组件会共享同一个请求  return (    &lt;&gt;      &lt;UserProfile userId={1} /&gt;      &lt;UserAvatar userId={1} /&gt;      &lt;UserName userId={1} /&gt;    &lt;/&gt;  );}function UserProfile({ userId }) {  const { data } = useQuery({    queryKey: ['user', userId],    queryFn: () =&gt; fetchUser(userId),  });  // ...}

并发请求管理12345678910111213141516171819202122232425262728class QueryCache {  constructor() {    this.queries = [];    this.queriesMap = {};    this.ongoingFetches = new Map(); // 正在进行的请求  }    async fetch(queryKey, queryFn) {    const queryHash = hashQueryKey(queryKey);        // 检查是否有相同的请求正在进行    if (this.ongoingFetches.has(queryHash)) {      return this.ongoingFetches.get(queryHash);    }        // 开始新请求    const fetchPromise = queryFn();    this.ongoingFetches.set(queryHash, fetchPromise);        try {      const result = await fetchPromise;      return result;    } finally {      // 请求完成后移除      this.ongoingFetches.delete(queryHash);    }  }}

八、Mutation 实现Mutation 类1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071727374757677787980class Mutation {  constructor(config) {    this.options = config.options;    this.mutationId = config.mutationId;        this.state = {      status: 'idle',      data: undefined,      error: null,    };        this.observers = [];  }    async execute(variables) {    this.state = {      status: 'loading',      data: undefined,      error: null,      variables,    };    this.notify();        try {      // 执行 onMutate 回调      const context = await this.options.onMutate?.(variables);            // 执行 mutation 函数      const data = await this.options.mutationFn(variables);            // 执行 onSuccess 回调      await this.options.onSuccess?.(data, variables, context);            this.state = {        status: 'success',        data,        error: null,        variables,      };            this.notify();      return data;          } catch (error) {      // 执行 onError 回调      await this.options.onError?.(error, variables);            this.state = {        status: 'error',        data: undefined,        error,        variables,      };            this.notify();      throw error;          } finally {      // 执行 onSettled 回调      await this.options.onSettled?.(        this.state.data,        this.state.error,        variables      );    }  }    subscribe(observer) {    this.observers.push(observer);    return () =&gt; {      this.observers = this.observers.filter((o) =&gt; o !== observer);    };  }    notify() {    this.observers.forEach((observer) =&gt; {      observer.notify();    });  }}

useMutation Hook12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849function useMutation(options) {  const client = useQueryClient();  const [, forceUpdate] = useReducer((x) =&gt; x + 1, 0);    const mutationRef = useRef();  if (!mutationRef.current) {    mutationRef.current = new Mutation({      mutationId: Date.now(),      options,    });  }    const mutation = mutationRef.current;    useEffect(() =&gt; {    const observer = {      notify: forceUpdate,    };        const unsubscribe = mutation.subscribe(observer);    return unsubscribe;  }, [mutation]);    const mutate = useCallback(    async (variables) =&gt; {      return mutation.execute(variables);    },    [mutation]  );    return {    mutate,    mutateAsync: mutate,    data: mutation.state.data,    error: mutation.state.error,    isLoading: mutation.state.status === 'loading',    isError: mutation.state.status === 'error',    isSuccess: mutation.state.status === 'success',    isIdle: mutation.state.status === 'idle',    reset: () =&gt; {      mutation.state = {        status: 'idle',        data: undefined,        error: null,      };      mutation.notify();    },  };}

九、高级特性实现1. 无限查询（Infinite Queries） InfiniteQuery extends Query {  constructor(config) {    super(config);    this.state = {      ...this.state,      data: {        pages: [],        pageParams: [],      },    };  }    async fetchNextPage() {    const { pages, pageParams } = this.state.data;    const lastPage = pages[pages.length - 1];        // 获取下一页的参数    const nextPageParam = this.options.getNextPageParam(      lastPage,      pages    );        if (nextPageParam === undefined) {      return; // 没有更多数据了    }        // 获取下一页数据    const newPage = await this.options.queryFn({      queryKey: this.queryKey,      pageParam: nextPageParam,    });        // 更新状态    this.state.data = {      pages: [...pages, newPage],      pageParams: [...pageParams, nextPageParam],    };        this.notify();  }    async fetchPreviousPage() {    const { pages, pageParams } = this.state.data;    const firstPage = pages[0];        const previousPageParam = this.options.getPreviousPageParam(      firstPage,      pages    );        if (previousPageParam === undefined) {      return;    }        const newPage = await this.options.queryFn({      queryKey: this.queryKey,      pageParam: previousPageParam,    });        this.state.data = {      pages: [newPage, ...pages],      pageParams: [previousPageParam, ...pageParams],    };        this.notify();  }}// useInfiniteQuery Hookfunction useInfiniteQuery(options) {  const client = useQueryClient();  const [, forceUpdate] = useReducer((x) =&gt; x + 1, 0);    const queryRef = useRef();  if (!queryRef.current) {    queryRef.current = new InfiniteQuery({      cache: client.getQueryCache(),      queryKey: options.queryKey,      options,    });  }    const query = queryRef.current;    useEffect(() =&gt; {    const observer = { notify: forceUpdate };    const unsubscribe = query.subscribe(observer);    return unsubscribe;  }, [query]);    return {    data: query.state.data,    fetchNextPage: () =&gt; query.fetchNextPage(),    fetchPreviousPage: () =&gt; query.fetchPreviousPage(),    hasNextPage: options.getNextPageParam(      query.state.data.pages[query.state.data.pages.length - 1],      query.state.data.pages    ) !== undefined,    hasPreviousPage: options.getPreviousPageParam(      query.state.data.pages[0],      query.state.data.pages    ) !== undefined,    // ...其他状态  };}// 使用示例function UserList() {  const {    data,    fetchNextPage,    hasNextPage,    isFetchingNextPage,  } = useInfiniteQuery({    queryKey: ['users'],    queryFn: ({ pageParam = 1 }) =&gt; fetchUsers(pageParam),    getNextPageParam: (lastPage, pages) =&gt; {      return lastPage.hasMore ? pages.length + 1 : undefined;    },  });    return (    &lt;div&gt;      {data?.pages.map((page, i) =&gt; (        &lt;div key={i}&gt;          {page.users.map((user) =&gt; (            &lt;div key={user.id}&gt;{user.name}&lt;/div&gt;          ))}        &lt;/div&gt;      ))}            &lt;button        onClick={() =&gt; fetchNextPage()}        disabled={!hasNextPage || isFetchingNextPage}      &gt;        {isFetchingNextPage ? '加载中...' : '加载更多'}      &lt;/button&gt;    &lt;/div&gt;  );}

2. 依赖查询（Dependent Queries）123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051function useQuery(options) {  const client = useQueryClient();  const [, forceUpdate] = useReducer((x) =&gt; x + 1, 0);    const queryRef = useRef();  const enabled = options.enabled !== false;    // 只有当 enabled 为 true 时才创建查询  if (!queryRef.current &amp;&amp; enabled) {    queryRef.current = client.getQueryCache().build(client, options);  }    const query = queryRef.current;    useEffect(() =&gt; {    if (!query || !enabled) return;        const observer = { notify: forceUpdate };    const unsubscribe = query.subscribe(observer);        // enabled 变化时可能需要重新获取    if (enabled &amp;&amp; query.state.fetchStatus === 'idle') {      query.fetch();    }        return unsubscribe;  }, [query, enabled]);    return {    data: query?.state.data,    // ...其他状态  };}// 使用示例function UserPosts({ userId }) {  // 先获取用户信息  const { data: user } = useQuery({    queryKey: ['user', userId],    queryFn: () =&gt; fetchUser(userId),  });    // 基于用户信息获取文章  const { data: posts } = useQuery({    queryKey: ['posts', user?.id],    queryFn: () =&gt; fetchPosts(user.id),    enabled: !!user, // 只有当 user 存在时才执行  });    return &lt;div&gt;{/* 渲染文章 */}&lt;/div&gt;;}

3. 并行查询1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859function useQueries(queries) {  const client = useQueryClient();  const [, forceUpdate] = useReducer((x) =&gt; x + 1, 0);    const queriesRef = useRef([]);    // 为每个查询创建 Query 实例  if (queriesRef.current.length === 0) {    queriesRef.current = queries.map((options) =&gt;      client.getQueryCache().build(client, options)    );  }    useEffect(() =&gt; {    const observers = queriesRef.current.map((query) =&gt; ({      notify: forceUpdate,    }));        const unsubscribes = queriesRef.current.map((query, index) =&gt;      query.subscribe(observers[index])    );        // 并行获取所有查询    queriesRef.current.forEach((query) =&gt; {      if (query.state.fetchStatus === 'idle') {        query.fetch();      }    });        return () =&gt; {      unsubscribes.forEach((unsubscribe) =&gt; unsubscribe());    };  }, []);    return queriesRef.current.map((query) =&gt; ({    data: query.state.data,    isLoading: query.state.status === 'loading',    error: query.state.error,  }));}// 使用示例function Dashboard() {  const results = useQueries([    { queryKey: ['users'], queryFn: fetchUsers },    { queryKey: ['posts'], queryFn: fetchPosts },    { queryKey: ['comments'], queryFn: fetchComments },  ]);    const [users, posts, comments] = results;    return (    &lt;div&gt;      {users.isLoading &amp;&amp; &lt;div&gt;加载用户...&lt;/div&gt;}      {posts.isLoading &amp;&amp; &lt;div&gt;加载文章...&lt;/div&gt;}      {comments.isLoading &amp;&amp; &lt;div&gt;加载评论...&lt;/div&gt;}    &lt;/div&gt;  );}

十、性能优化技术1. 结构共享（Structural Sharing）12345678910111213141516171819202122232425262728293031323334353637383940414243444546// 深度比较并共享未变化的数据结构function replaceEqualDeep(a, b) {  if (a === b) return a;    const array = Array.isArray(a) &amp;&amp; Array.isArray(b);    if (array || (isPlainObject(a) &amp;&amp; isPlainObject(b))) {    const aSize = array ? a.length : Object.keys(a).length;    const bSize = array ? b.length : Object.keys(b).length;    const aItems = array ? a : Object.keys(a);    const bItems = array ? b : Object.keys(b);    const copy = array ? [] : {};        let equalItems = 0;        for (let i = 0; i &lt; bSize; i++) {      const key = array ? i : bItems[i];      copy[key] = replaceEqualDeep(a[key], b[key]);      if (copy[key] === a[key]) {        equalItems++;      }    }        return aSize === bSize &amp;&amp; equalItems === aSize ? a : copy;  }    return b;}// 在 Query 中应用class Query {  setData(updater) {    const prevData = this.state.data;    const data = typeof updater === 'function'       ? updater(prevData)       : updater;        // 使用结构共享优化    const sharedData = replaceEqualDeep(prevData, data);        if (sharedData !== prevData) {      this.state.data = sharedData;      this.notify();    }  }}

2. 选择器优化12345678910111213141516171819202122232425// 使用选择器只订阅需要的数据function useUserName(userId) {  return useQuery({    queryKey: ['user', userId],    queryFn: () =&gt; fetchUser(userId),    select: (data) =&gt; data.name, // 只选择 name 字段  });}// 实现 select 选项function useQuery(options) {  // ...    const selectFn = options.select;  let selectedData = query.state.data;    if (selectFn &amp;&amp; selectedData !== undefined) {    selectedData = selectFn(selectedData);  }    return {    data: selectedData,    // ...  };}

3. 批量更新123456789101112131415161718192021222324252627282930313233class QueryClient {  constructor() {    this.batchedUpdates = [];    this.isBatching = false;  }    batch(fn) {    this.isBatching = true;    fn();    this.isBatching = false;    this.flush();  }    notify(update) {    if (this.isBatching) {      this.batchedUpdates.push(update);    } else {      update();    }  }    flush() {    this.batchedUpdates.forEach((update) =&gt; update());    this.batchedUpdates = [];  }}// 使用示例queryClient.batch(() =&gt; {  queryClient.setQueryData(['user', 1], newUser1);  queryClient.setQueryData(['user', 2], newUser2);  queryClient.setQueryData(['user', 3], newUser3);}); // 只触发一次重渲染

十一、总结核心原理总结
QueryClient + QueryCache：管理所有查询的中心
Query 实例：单个查询的状态机
观察者模式：订阅机制实现响应式更新
请求去重：避免重复请求
缓存策略：多层次的缓存管理
结构共享：优化内存和渲染性能

