三、数组展开3.1 一维数组展开1234567// 方法 1：扩展运算符const arr1 = [1, 2, 3];const arr2 = [4, 5, 6];const merged = [...arr1, ...arr2];  // [1, 2, 3, 4, 5, 6]// 方法 2：concat()const merged2 = arr1.concat(arr2);  // [1, 2, 3, 4, 5, 6]

3.2 多维数组展平12345678910111213141516171819202122232425262728293031323334353637const arr = [1, [2, [3, [4, 5]]]];// 方法 1：flat()（指定深度）arr.flat(1);        // [1, 2, [3, [4, 5]]]arr.flat(2);        // [1, 2, 3, [4, 5]]arr.flat(Infinity); // [1, 2, 3, 4, 5]// 方法 2：递归实现function flatten(arr) {  return arr.reduce((acc, cur) =&gt; {    return acc.concat(Array.isArray(cur) ? flatten(cur) : cur);  }, []);}flatten(arr);  // [1, 2, 3, 4, 5]// 方法 3：toString() + split()（仅数字）arr.toString().split(',').map(Number);  // [1, 2, 3, 4, 5]// 方法 4：栈实现function flattenByStack(arr) {  const stack = [...arr];  const result = [];    while (stack.length) {    const item = stack.pop();    if (Array.isArray(item)) {      stack.push(...item);    } else {      result.unshift(item);    }  }    return result;}flattenByStack(arr);  // [1, 2, 3, 4, 5]


四、数组去重4.1 基本方法123456789101112131415const arr = [1, 2, 2, 3, 3, 4, 5, 5];// 方法 1：Setconst unique1 = [...new Set(arr)];  // [1, 2, 3, 4, 5]// 方法 2：filter + indexOfconst unique2 = arr.filter((item, index) =&gt; arr.indexOf(item) === index);// 方法 3：reduceconst unique3 = arr.reduce((acc, cur) =&gt; {  return acc.includes(cur) ? acc : [...acc, cur];}, []);// 方法 4：Mapconst unique4 = [...new Map(arr.map(item =&gt; [item, item])).values()];

4.2 对象数组去重123456789101112131415161718192021const arr = [  { id: 1, name: 'Alice' },  { id: 2, name: 'Bob' },  { id: 1, name: 'Alice' }];// 方法 1：根据 id 去重const unique = arr.reduce((acc, cur) =&gt; {  const exists = acc.find(item =&gt; item.id === cur.id);  return exists ? acc : [...acc, cur];}, []);// 方法 2：使用 Mapconst map = new Map();arr.forEach(item =&gt; map.set(item.id, item));const unique2 = [...map.values()];// 方法 3：filterconst unique3 = arr.filter((item, index, self) =&gt;   index === self.findIndex(t =&gt; t.id === item.id));


五、防抖与节流5.1 防抖（debounce）1234567891011121314151617// 延迟执行，最后一次触发后才执行function debounce(func, delay) {  let timer = null;    return function(...args) {    clearTimeout(timer);    timer = setTimeout(() =&gt; {      func.apply(this, args);    }, delay);  };}// 使用示例const input = document.querySelector('#search');input.addEventListener('input', debounce(function(e) {  console.log('搜索:', e.target.value);}, 500));

5.2 节流（throttle）12345678910111213141516171819// 固定时间间隔执行一次function throttle(func, delay) {  let timer = null;  let lastTime = 0;    return function(...args) {    const now = Date.now();        if (now - lastTime &gt;= delay) {      func.apply(this, args);      lastTime = now;    }  };}// 使用示例window.addEventListener('scroll', throttle(function() {  console.log('滚动位置:', window.scrollY);}, 200));


六、深拷贝实现12345678910111213141516171819202122232425262728293031323334353637383940function deepClone(obj, hash = new WeakMap()) {  // null 或基本类型  if (obj === null || typeof obj !== 'object') {    return obj;  }    // Date  if (obj instanceof Date) {    return new Date(obj);  }    // RegExp  if (obj instanceof RegExp) {    return new RegExp(obj);  }    // 处理循环引用  if (hash.has(obj)) {    return hash.get(obj);  }    // 创建新对象  const cloneObj = Array.isArray(obj) ? [] : {};  hash.set(obj, cloneObj);    // 拷贝属性  for (let key in obj) {    if (obj.hasOwnProperty(key)) {      cloneObj[key] = deepClone(obj[key], hash);    }  }    return cloneObj;}// 使用const obj = { a: 1, b: { c: 2 } };const copy = deepClone(obj);copy.b.c = 3;console.log(obj.b.c);  // 2 ✅


