九、Promise 相关9.1 实现 Promise.all()123456789101112131415161718192021222324function promiseAll(promises) {  return new Promise((resolve, reject) =&gt; {    if (!Array.isArray(promises)) {      return reject(new TypeError('参数必须是数组'));    }        const results = [];    let count = 0;        promises.forEach((promise, index) =&gt; {      Promise.resolve(promise).then(        value =&gt; {          results[index] = value;          count++;                    if (count === promises.length) {            resolve(results);          }        },        reason =&gt; reject(reason)      );    });  });}

