3.2 使用 requestAnimationFrame123456789101112// ❌ 使用 setTimeoutfunction animate() {  element.style.transform = `translateX(${x}px)`;  setTimeout(animate, 16);  // 不精确}// ✅ 使用 requestAnimationFramefunction animate() {  element.style.transform = `translateX(${x}px)`;  requestAnimationFrame(animate);  // 60fps}requestAnimationFrame(animate);

3.3 虚拟列表123456789101112131415161718192021// React 虚拟列表示例import { FixedSizeList } from 'react-window';function VirtualList({ items }) {  const Row = ({ index, style }) =&gt; (    &lt;div style={style}&gt;      {items[index].name}    &lt;/div&gt;  );    return (    &lt;FixedSizeList      height={600}      itemCount={items.length}      itemSize={50}      width="100%"    &gt;      {Row}    &lt;/FixedSizeList&gt;  );}

3.4 防抖节流12345678910111213141516171819202122232425// 防抖：延迟执行function debounce(fn, delay) {  let timer = null;  return function(...args) {    clearTimeout(timer);    timer = setTimeout(() =&gt; fn.apply(this, args), delay);  };}// 节流：固定间隔执行function throttle(fn, delay) {  let lastTime = 0;  return function(...args) {    const now = Date.now();    if (now - lastTime &gt;= delay) {      fn.apply(this, args);      lastTime = now;    }  };}// 使用window.addEventListener('scroll', throttle(() =&gt; {  console.log('滚动');}, 200));


