五、JavaScript 性能优化5.1 避免全局变量1234567891011121314151617181920// ❌ 全局变量var count = 0;function increment() {  count++;}// ✅ 模块化const Counter = (function() {  let count = 0;    return {    increment() {      count++;    },    getCount() {      return count;    }  };})();

