七、React 性能优化7.1 使用 React.memo12345678910111213141516// 防止不必要的重新渲染const ChildComponent = React.memo(({ name }) =&gt; {  console.log('渲染');  return &lt;div&gt;{name}&lt;/div&gt;;});function Parent() {  const [count, setCount] = useState(0);    return (    &lt;div&gt;      &lt;button onClick={() =&gt; setCount(count + 1)}&gt;+&lt;/button&gt;      &lt;ChildComponent name="Alice" /&gt;  {/* count 变化不会重新渲染 */}    &lt;/div&gt;  );}

7.2 使用 useMemo 和 useCallback123456789101112131415161718function Component({ items }) {  // useMemo：缓存计算结果  const expensiveValue = useMemo(() =&gt; {    return items.reduce((sum, item) =&gt; sum + item.value, 0);  }, [items]);    // useCallback：缓存函数  const handleClick = useCallback(() =&gt; {    console.log('点击');  }, []);    return (    &lt;div&gt;      &lt;div&gt;{expensiveValue}&lt;/div&gt;      &lt;button onClick={handleClick}&gt;点击&lt;/button&gt;    &lt;/div&gt;  );}

7.3 代码分割1234567891011import { lazy, Suspense } from 'react';const HeavyComponent = lazy(() =&gt; import('./HeavyComponent'));function App() {  return (    &lt;Suspense fallback={&lt;div&gt;Loading...&lt;/div&gt;}&gt;      &lt;HeavyComponent /&gt;    &lt;/Suspense&gt;  );}


