前端安全合集Web 安全是前端开发中不可忽视的重要环节。本文将详细介绍常见的前端安全问题及其防范措施。
一、XSS 攻击1.1 什么是 XSSXSS（Cross-Site Scripting，跨站脚本攻击）是指攻击者在网页中注入恶意脚本代码，当用户访问时，这些代码会在用户浏览器中执行。
1.2 XSS 类型反射型 XSS（非持久型）12345678// 攻击示例// URL: http://example.com/search?q=&lt;script&gt;alert('XSS')&lt;/script&gt;// 后端直接返回用户输入app.get('/search', (req, res) =&gt; {  const query = req.query.q;  res.send(`搜索结果：${query}`);  // ❌ 直接输出，存在 XSS 风险});

存储型 XSS（持久型）12345678910// 攻击示例：评论系统// 用户提交评论：&lt;script&gt;document.cookie&lt;/script&gt;// 后端存储到数据库db.comments.insert({  content: req.body.content  // ❌ 未过滤，存储了恶意脚本});// 其他用户访问时，脚本执行res.send(`&lt;div&gt;${comment.content}&lt;/div&gt;`);  // ❌ 直接输出

DOM 型 XSS12345678&lt;!-- 攻击示例 --&gt;&lt;!-- URL: http://example.com#&lt;img src=x onerror=alert('XSS')&gt; --&gt;&lt;script&gt;// ❌ 直接使用 URL 参数const hash = location.hash.slice(1);document.getElementById('content').innerHTML = hash;&lt;/script&gt;

1.3 XSS 防御方法 1：输入过滤12345678910111213141516// 服务端过滤function escapeHtml(str) {  const map = {    '&amp;': '&amp;amp;',    '&lt;': '&amp;lt;',    '&gt;': '&amp;gt;',    '"': '&amp;quot;',    "'": '&amp;#x27;',    '/': '&amp;#x2F;'  };  return str.replace(/[&amp;&lt;&gt;"'/]/g, char =&gt; map[char]);}// 使用const userInput = req.body.content;const safeInput = escapeHtml(userInput);

方法 2：输出编码12345678910111213// React 自动转义function Comment({ content }) {  return &lt;div&gt;{content}&lt;/div&gt;;  // ✅ React 自动转义}// Vue 自动转义&lt;template&gt;  &lt;div&gt;{{ content }}&lt;/div&gt;  &lt;!-- ✅ Vue 自动转义 --&gt;&lt;/template&gt;// 危险的用法&lt;div dangerouslySetInnerHTML={{ __html: content }} /&gt;  // ❌ 绕过转义&lt;div v-html="content"&gt;&lt;/div&gt;  &lt;!-- ❌ 绕过转义 --&gt;

方法 3：Content Security Policy（CSP）12&lt;!-- HTTP 头部 --&gt;&lt;meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self' https://trusted.cdn.com"&gt;

12345678// Express 设置 CSPapp.use((req, res, next) =&gt; {  res.setHeader(    'Content-Security-Policy',    "default-src 'self'; script-src 'self' 'unsafe-inline'"  );  next();});

方法 4：使用安全的 API12345678// ❌ 不安全element.innerHTML = userInput;document.write(userInput);eval(userInput);// ✅ 安全element.textContent = userInput;element.setAttribute('data-value', userInput);

方法 5：使用 DOMPurify 库123456import DOMPurify from 'dompurify';const dirty = '&lt;img src=x onerror=alert("XSS")&gt;';const clean = DOMPurify.sanitize(dirty);element.innerHTML = clean;  // ✅ 安全


二、CSRF 攻击2.1 什么是 CSRFCSRF（Cross-Site Request Forgery，跨站请求伪造）是指攻击者诱导用户在已登录的网站上执行非本意的操作。
2.2 CSRF 攻击示例1234567891011121314151617&lt;!-- 攻击者网站 --&gt;&lt;!DOCTYPE html&gt;&lt;html&gt;&lt;body&gt;  &lt;!-- 用户点击后，自动发送请求到银行网站 --&gt;  &lt;img src="https://bank.com/transfer?to=attacker&amp;amount=1000" style="display:none"&gt;    &lt;form action="https://bank.com/transfer" method="POST" id="hack"&gt;    &lt;input type="hidden" name="to" value="attacker"&gt;    &lt;input type="hidden" name="amount" value="1000"&gt;  &lt;/form&gt;    &lt;script&gt;    document.getElementById('hack').submit();  &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;

2.3 CSRF 防御方法 1：CSRF Token123456789101112// 服务端生成 Tokenconst csrf = require('csurf');const csrfProtection = csrf({ cookie: true });app.get('/form', csrfProtection, (req, res) =&gt; {  res.render('form', { csrfToken: req.csrfToken() });});app.post('/submit', csrfProtection, (req, res) =&gt; {  // Token 验证通过  res.send('Success');});

12345&lt;!-- 前端使用 Token --&gt;&lt;form action="/submit" method="POST"&gt;  &lt;input type="hidden" name="_csrf" value="{{csrfToken}}"&gt;  &lt;button type="submit"&gt;提交&lt;/button&gt;&lt;/form&gt;

方法 2：SameSite Cookie123456// 设置 Cookie 的 SameSite 属性res.cookie('sessionId', 'abc123', {  httpOnly: true,  secure: true,  sameSite: 'strict'  // 或 'lax'});


strict：完全禁止第三方请求携带 Cookie
lax：允许导航到目标网址的 GET 请求携带 Cookie
none：无限制（需 HTTPS）

方法 3：验证 Referer123456789app.post('/api/transfer', (req, res) =&gt; {  const referer = req.headers.referer;    if (!referer || !referer.startsWith('https://bank.com')) {    return res.status(403).send('Forbidden');  }    // 处理请求});

方法 4：自定义请求头123456789101112131415161718// 前端添加自定义头部fetch('/api/data', {  method: 'POST',  headers: {    'X-Requested-With': 'XMLHttpRequest',    'X-CSRF-Token': token  },  body: JSON.stringify(data)});// 服务端验证app.post('/api/data', (req, res) =&gt; {  if (req.headers['x-requested-with'] !== 'XMLHttpRequest') {    return res.status(403).send('Forbidden');  }    // 处理请求});


三、点击劫持3.1 什么是点击劫持点击劫持（Clickjacking）是指攻击者使用透明的 iframe 覆盖在正常页面上，诱导用户点击。
3.2 攻击示例123456789101112131415161718192021&lt;!-- 攻击者网站 --&gt;&lt;!DOCTYPE html&gt;&lt;html&gt;&lt;head&gt;  &lt;style&gt;    #target {      opacity: 0;  /* 透明 */      position: absolute;      top: 0;      left: 0;      width: 100%;      height: 100%;      z-index: 1000;    }  &lt;/style&gt;&lt;/head&gt;&lt;body&gt;  &lt;h1&gt;点击领取奖品&lt;/h1&gt;  &lt;iframe id="target" src="https://bank.com/transfer"&gt;&lt;/iframe&gt;&lt;/body&gt;&lt;/html&gt;

3.3 防御措施方法 1：X-Frame-Options12345// 禁止被嵌入 iframeapp.use((req, res, next) =&gt; {  res.setHeader('X-Frame-Options', 'DENY');  // 或 'SAMEORIGIN'  next();});

12# Nginx 配置add_header X-Frame-Options "SAMEORIGIN";

方法 2：CSP frame-ancestors1234res.setHeader(  'Content-Security-Policy',  "frame-ancestors 'self'");

方法 3：JavaScript 防御1234// 检测是否被嵌入if (top !== self) {  top.location = self.location;  // 跳出 iframe}


四、SQL 注入4.1 攻击示例123456789101112131415// ❌ 不安全：字符串拼接app.post('/login', (req, res) =&gt; {  const username = req.body.username;  const password = req.body.password;    const query = `SELECT * FROM users WHERE username = '${username}' AND password = '${password}'`;    db.query(query, (err, results) =&gt; {    // ...  });});// 攻击输入：username = "admin' --"// 生成的 SQL：SELECT * FROM users WHERE username = 'admin' --' AND password = ''// -- 注释掉后面的 password 检查

4.2 防御措施12345678910111213141516171819// ✅ 使用参数化查询app.post('/login', (req, res) =&gt; {  const username = req.body.username;  const password = req.body.password;    const query = 'SELECT * FROM users WHERE username = ? AND password = ?';    db.query(query, [username, password], (err, results) =&gt; {    // ✅ 参数会被自动转义  });});// ✅ 使用 ORMconst user = await User.findOne({  where: {    username: req.body.username,    password: req.body.password  }});


五、敏感信息泄露5.1 常见泄露途径12345678910111213// ❌ 敏感信息暴露const config = {  apiKey: 'sk-1234567890',  // ❌ 硬编码  dbPassword: 'password123'};// ❌ 前端暴露console.log('用户密码:', user.password);// ❌ 错误信息泄露app.use((err, req, res, next) =&gt; {  res.status(500).send(err.stack);  // ❌ 暴露堆栈信息});

5.2 防御措施1234567891011121314151617181920212223// ✅ 使用环境变量const config = {  apiKey: process.env.API_KEY,  dbPassword: process.env.DB_PASSWORD};// ✅ 后端过滤敏感字段const user = await User.findById(id);const safeUser = {  id: user.id,  username: user.username,  email: user.email  // 不返回 password、salt 等敏感信息};// ✅ 生产环境隐藏错误详情app.use((err, req, res, next) =&gt; {  if (process.env.NODE_ENV === 'production') {    res.status(500).send('Internal Server Error');  } else {    res.status(500).send(err.stack);  }});


六、中间人攻击（MITM）6.1 防御措施使用 HTTPS123456789101112131415# Nginx 配置 HTTPSserver {  listen 443 ssl;  ssl_certificate /path/to/cert.pem;  ssl_certificate_key /path/to/key.pem;    ssl_protocols TLSv1.2 TLSv1.3;  ssl_ciphers HIGH:!aNULL:!MD5;}# HTTP 重定向到 HTTPSserver {  listen 80;  return 301 https://$host$request_uri;}

HSTS（HTTP Strict Transport Security）12345// 强制使用 HTTPSres.setHeader(  'Strict-Transport-Security',  'max-age=31536000; includeSubDomains; preload');


七、第三方依赖安全7.1 依赖检查12345678# npm 审计npm audit# 自动修复npm audit fix# yarn 审计yarn audit

7.2 使用 Snyk12345678# 安装 Snyknpm install -g snyk# 测试项目snyk test# 监控项目snyk monitor

7.3 锁定依赖版本1234567// package.json{  "dependencies": {    "express": "4.18.2",  // ✅ 固定版本    // "express": "^4.18.2"  // ❌ 允许更新次版本  }}


八、安全最佳实践8.1 密码安全123456789101112131415161718const bcrypt = require('bcrypt');// ✅ 加密存储密码async function hashPassword(password) {  const salt = await bcrypt.genSalt(10);  return await bcrypt.hash(password, salt);}// ✅ 验证密码async function verifyPassword(password, hash) {  return await bcrypt.compare(password, hash);}// 使用const hashedPassword = await hashPassword('user-password');// 存储 hashedPassword 到数据库const isValid = await verifyPassword('user-input', hashedPassword);

8.2 JWT 安全12345678910111213141516171819const jwt = require('jsonwebtoken');// ✅ 生成 Tokenconst token = jwt.sign(  { userId: user.id },  process.env.JWT_SECRET,  // 使用环境变量  {    expiresIn: '1h',  // 设置过期时间    algorithm: 'HS256'  });// ✅ 验证 Tokentry {  const decoded = jwt.verify(token, process.env.JWT_SECRET);  console.log(decoded.userId);} catch (err) {  console.error('Token 无效');}

8.3 文件上传安全1234567891011121314151617181920212223242526272829const multer = require('multer');const path = require('path');// ✅ 验证文件类型const storage = multer.diskStorage({  destination: './uploads/',  filename: (req, file, cb) =&gt; {    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);    cb(null, uniqueSuffix + path.extname(file.originalname));  }});const upload = multer({  storage,  limits: {    fileSize: 5 * 1024 * 1024  // 5MB  },  fileFilter: (req, file, cb) =&gt; {    const allowedTypes = /jpeg|jpg|png|gif/;    const extname = allowedTypes.test(path.extname(file.originalname).toLowerCase());    const mimetype = allowedTypes.test(file.mimetype);        if (extname &amp;&amp; mimetype) {      cb(null, true);    } else {      cb(new Error('只允许上传图片'));    }  }});


九、安全检查清单前端安全
